using System;
using System.Threading.Tasks;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using FluentSeq;
using XTA.Core;
using XTA.Models;

namespace XTA
{
    /// <summary>
    /// .NET IHost 기반으로 고도화된 최종 XTA 스타트업 엔진
    /// </summary>
    public class XTAStartupV2
    {
        // 로거는 이제 Host에서 제공하는 표준 ILogger 사용 권장 (기존 static nlog 유지 병행)
        private static NLog.Logger nlog = NLog.LogManager.GetCurrentClassLogger();

        public static async Task RunAsync()
        {
            var ctx = XContext.Instance;

            var sequence = new FluentSeq<string>().Create("XTA_HOST_STARTUP")
                .Step("InitializeParameter", () => {
                    // 1. 파라미터 초기화 (NLog 초기 설정 포함)
                    var parameter = new XParameter();
                    ctx.Parameter = parameter;
                    return true;
                })
                .Step("BuildStandardHost", () => {
                    // 2. IHost 빌드 및 XContext 바인딩
                    var host = XTAHostBuilder.Build(ctx.Parameter);
                    ctx.Initialize(host, ctx.Parameter);
                    nlog.Info("[Startup] .NET Generic Host built and bound to XContext.");
                    return true;
                })
                .Step("StartHost", async () => {
                    // 3. Host 실행 (백그라운드 서비스들 시작)
                    await ctx.GetService<IHost>().StartAsync();
                    nlog.Info("[Startup] IHost started.");
                    return true;
                })
                .Step("LegacyStartBridge", () => {
                    // 4. 기존 XObject 기반 서비스들 시작 (호환성 유지)
                    ctx.Parameter.StartAll();
                    return true;
                })
                .OnFailure(err => {
                    nlog.Fatal($"[Startup:FATAL] Host startup failed at {err.StateName}: {err.Exception?.Message}");
                })
                .Build();

            await sequence.StartAsync();
        }

        /// <summary>
        /// 데이터 이관 시퀀스 (Host 기반)
        /// </summary>
        public static async Task ProcessTransferAsync()
        {
            var ctx = XContext.Instance;
            
            var transferSeq = new FluentSeq<string>().Create("DATA_TRANSFER")
                .Step("ScanClosedSignals", async () => {
                    var repo = ctx.SignalRepo;
                    if (repo == null) return false;
                    var closedSignals = await repo.GetClosedSignalsAsync();
                    return closedSignals.Count > 0;
                })
                .Step("ExecuteTransfer", async () => {
                    var dataSvc = ctx.Data;
                    if (dataSvc == null) return false;
                    
                    nlog.Info("[Transfer] Moving closed signals to history via Host DataService...");
                    await dataSvc.ArchiveSignalsAsync();
                    return true;
                })
                .OnSuccess(() => nlog.Info("[Transfer] Data migration completed successfully."))
                .Build();

            await transferSeq.StartAsync();
        }
    }
}

