using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using NLog;
using XTA.Core;
using XTA.Interfaces;
using XTA.Models;
using XTA.XData.Interfaces;
using XTA.XData.Models;

namespace XTA.Services
{
    public class XLiquidationService : IXLiquidationService
    {
        private static readonly Logger nlog = LogManager.GetCurrentClassLogger();

        public async Task ProcessLiquidationAsync(Models.XSignal signal, int msgId)
        {
            var ctx = XContext.Instance;
            var gateway = ctx.Gateway as XGatewayService;
            var dbService = ctx.Parameter.GetService<XpoSqliteService>();
            var repo = ctx.Parameter.GetService<ISignalRepository>();

            nlog.Info($"[Liquidation] >>> Starting Close Process for CNO:{signal.cno} SNO:{signal.sno} (MsgId:{msgId})");

            var targets = new List<XTA.XData.Models.XSignal>();

            // 1. 메모리(Pending) 검색
            if (gateway != null)
            {
                var pendingMatches = gateway.PendingSignals.Values
                    .Where(x => x.Signal != null && x.Signal.cno == signal.cno && x.Signal.sno == signal.sno)
                    .Select(x => (XTA.XData.Models.XSignal)x.Signal!)
                    .ToList();

                if (pendingMatches.Any())
                {
                    targets.AddRange(pendingMatches);
                    nlog.Info($"[Liquidation] Matched {pendingMatches.Count} signals from Gateway Memory Cache.");
                }
            }

            // 2. DB 검색
            if (dbService != null)
            {
                var dbMatches = await dbService.FindActiveSignalsBySnoAsync(signal.cno, signal.sno);
                int dbCount = 0;
                foreach (var dbm in dbMatches)
                {
                    if (!targets.Any(t => t.sid == dbm.sid)) 
                    {
                        targets.Add(dbm);
                        dbCount++;
                    }
                }
                if (dbCount > 0) nlog.Info($"[Liquidation] Matched {dbCount} additional signals from Database.");
            }

            if (targets.Count > 0)
            {
                foreach (var targetEntry in targets)
                {
                    var finalSignal = targetEntry as Models.XSignal ?? Models.XSignal.FromBase(targetEntry);

                    if (gateway != null && gateway.PendingSignals.TryRemove(finalSignal.sid, out _))
                    {
                        // SignalRemoved 이벤트는 게이트웨이에서 발생시켜야 함 (인터페이스 수정 필요할 수 있음)
                    }

                    finalSignal.msg_id = msgId;
                    finalSignal.cmd = XCode.CLOSE;
                    finalSignal.xa_exit = (int)XCode.XA_ACTIVE;
                    finalSignal.updated = DateTime.Now;

                    if (ctx.Data != null) await ctx.Data.SaveSignalAsync(finalSignal);

                    var signalXdo = new XDataObject { Signal = finalSignal, MsgId = msgId, CMD = "CLOSE_SIGNAL" };
                    // SignalAddedOrUpdated 이벤트도 게이트웨이 전담
                }

                ctx.Gateway?.Log($"[{signal.cno}] {signal.sno}회차 청산 처리 완료 ({targets.Count}건)");
                string soundCmd = (signal.sno == 0) ? "GROUP_CLOSE" : "SID_CLOSE";
                ctx.Sound?.PlaySound(signal, soundCmd);
            }
            else
            {
                nlog.Warn($"[Liquidation:FORCE] No active signal found for CNO:{signal.cno} SNO:{signal.sno}. Generating forced record.");

                var lastActive = await dbService!.FindLastActiveSignalBySnoAsync(signal.cno, signal.sno);
                int validDir = lastActive?.dir ?? (signal.dir > 0 ? signal.dir : 1);

                var finalSignal = signal;
                finalSignal.dir = validDir;
                finalSignal.type = 9;
                finalSignal.sid = XIdManager.Instance.GenerateSid(finalSignal.cno, DateTime.Now, finalSignal.sno, 0, finalSignal.dir, 9);
                finalSignal.gid = XIdManager.Instance.GenerateGid(finalSignal.cno, DateTime.Now, finalSignal.sno);
                finalSignal.symbol = "GOLD";
                finalSignal.lot = 0.0;

                finalSignal.msg_id = msgId;
                finalSignal.cmd = XCode.CLOSE;
                finalSignal.type = 9;
                finalSignal.xa_exit = (int)XCode.XA_ACTIVE;
                finalSignal.SetXeStatus((int)XCode.EaStatus.Closed_Signal); 
                finalSignal.updated = DateTime.Now;

                if (ctx.Data != null) await ctx.Data.SaveSignalAsync(finalSignal);

                var signalXdo = new XDataObject { Signal = finalSignal, MsgId = msgId, CMD = "CLOSE_SIGNAL" };
                // 이벤트 처리 필요

                ctx.Gateway?.Log($"[{finalSignal.cno}] {finalSignal.sno}회차 활성 신호 없음 - 강제 청산 레코드 생성 (SID:{finalSignal.sid})");
                ctx.Sound?.PlaySound(finalSignal, "SID_CLOSE");
            }
            nlog.Info($"[Liquidation] <<< Close Process Finished for CNO:{signal.cno} SNO:{signal.sno}");
        }
    }
}

using NLog;
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using XTA.Infrastructure.Data;
using XTA.XData.Interfaces;
using XTA.XData.Models;
using static XTA.XData.Models.XCode;
using XTA.Models;
using XTA.Interfaces;
using XTA.Core;
using FluentSeq;
using System.Threading.Tasks;
using System.Threading.Channels;
using System.Threading;

namespace XTA.Services
{
    /// <summary>
    /// 텔레그램 메시지와 인터프리터 사이의 관문 역할을 하는 서비스.
    /// [Thread-Safe] 생산자-소비자 패턴 및 FluentSeq 상태 머신을 적용함.
    /// </summary>
    public class XGatewayService : XChannelObject, IXGatewayService
    {
        public ConcurrentDictionary<string, XDataObject> PendingSignals { get; } = new();

        public event Action<XDataObject>? SignalAddedOrUpdated;
        public event Action<string>? SignalRemoved;

        private ISequence<HubState> _msgSeq = null!;
        private ISequence<string> _procSeq = null!; // 신호 처리 전용 시퀀스

        private readonly Channel<XDataObject> _msgChannel = Channel.CreateUnbounded<XDataObject>();
        private readonly Channel<XDataObject> _interpretedChannel = Channel.CreateUnbounded<XDataObject>();
        private CancellationTokenSource? _cts;

        // 메시지 소비자 컨텍스트
        private XDataObject? _currentXdo;
        private XChannelInfo? _currentInfo;

        // 신호 처리 소비자 컨텍스트
        private XDataObject? _currentInterpretedXdo;
        private List<Models.XSignal>? _preparedSignals;

        public XGatewayService(XParameter param) : base(param, new XChannelInfo(0, 0, "GATEWAY_HUB", "SYSTEM"))
        {
            InitSequences();
        }

        private void InitSequences()
        {
            // 1. 메시지 라우팅 시퀀스
            _msgSeq = new FluentSeq<HubState>()
                .Create(HubState.Received)
                .ActivateDebugLogging(nlog)
                .ConfigureState(HubState.Received)
                    .OnEntry(() => {
                        if (_currentXdo == null) return;
                        if (_currentInfo != null) {
                            _currentXdo.CNO = _currentInfo.CNO;
                            _ = XContext.Instance.Data?.SaveMessageAsync(_currentXdo);
                            this.Log($"[TG] {_currentInfo.Name} 채널 메시지 수신 (MsgId:{_currentXdo.MsgId})");
                        }
                    })
                .ConfigureState(HubState.Interpreted)
                    .TriggeredBy(() => _currentInfo != null && _currentInfo.Type.ToUpper() == "TRADE" && _currentInfo.CNO != 2001 && _currentInfo.CNO != 2002)
                        .WhenInState(HubState.Received)
                    .OnEntry(() => {
                        var interpreter = param.GetService<XInterpreterBase>(i => i.Info.CNO == _currentInfo!.CNO);
                        if (interpreter != null) interpreter.EnqueueMessage(_currentXdo!);
                        else nlog.Warn($"[Gateway:FAIL] Interpreter not found for CNO:{_currentInfo!.CNO}");
                    })
                .ConfigureState(HubState.Failed)
                    .TriggeredBy(() => _currentInfo == null || (_currentInfo.Type.ToUpper() != "TRADE" || _currentInfo.CNO == 2001 || _currentInfo.CNO == 2002))
                        .WhenInState(HubState.Received)
                .Builder().DisableValidation().Build();

            // 2. 신호 처리 시퀀스 (OnSignalInterpretedInternalAsync 대체)
            _procSeq = new FluentSeq<string>()
                .Create("Idle")
                .ActivateDebugLogging(nlog)
                .ConfigureState("Idle")
                .ConfigureState("Enrich")
                    .OnEntry(async () => {
                        if (_currentInterpretedXdo == null) { _procSeq.SetState("Idle"); return; }
                        var ctx = XContext.Instance;
                        _preparedSignals = await ctx.Signal.PrepareSignalsAsync(_currentInterpretedXdo);

                        if (_preparedSignals == null || _preparedSignals.Count == 0) {
                            nlog.Warn($"[Gateway:DROP] No valid signals for MsgId:{_currentInterpretedXdo.MsgId}");
                            _procSeq.SetState("Idle");
                        } else {
                            _procSeq.SetState("Dispatch");
                        }
                    })
                .ConfigureState("Dispatch")
                    .OnEntry(async () => {
                        if (_preparedSignals == null) { _procSeq.SetState("Idle"); return; }
                        var ctx = XContext.Instance;

                        foreach (var s in _preparedSignals) {
                            if (s.cmd == XCode.CLOSE) {
                                await ctx.Liquidation.ProcessLiquidationAsync(s, _currentInterpretedXdo!.MsgId);
                                continue;
                            }

                            var signalXdo = new XDataObject { 
                                Signal = s, MsgId = _currentInterpretedXdo!.MsgId, 
                                Text = _currentInterpretedXdo.Text, CID = _currentInterpretedXdo.CID, CNO = _currentInterpretedXdo.CNO 
                            };
                            PendingSignals.AddOrUpdate(s.sid, signalXdo, (k, v) => signalXdo);

                            if (ctx.Data != null) await ctx.Data.SaveSignalAsync(s);
                            ctx.Sound?.PlaySound(s, "SIGNAL_RECEIVED");
                            SignalAddedOrUpdated?.Invoke(signalXdo);
                        }
                        _procSeq.SetState("Idle");
                    })
                .Builder().DisableValidation().Build();
        }

        public void EnqueueRawMessage(XDataObject xdo) => OnRawMessageReceived(xdo);

        public void Log(string message) => nlog.Info($"[LOG:HUB] {message}");

        private bool _isStarted = false;
        private readonly HashSet<int> _processedMsgIds = new();

        public override void Start()
        {
            lock (_processedMsgIds) { if (_isStarted) return; _isStarted = true; }
            _cts = new CancellationTokenSource();
            Task.Run(() => ProcessMessageQueueAsync(_cts.Token));
            Task.Run(() => ProcessInterpretedQueueAsync(_cts.Token));
        }

        public override void Stop() { _cts?.Cancel(); _isStarted = false; }

        private void OnRawMessageReceived(XDataObject xdo)
        {
            if (xdo == null) return;
            lock (_processedMsgIds) {
                if (_processedMsgIds.Contains(xdo.MsgId)) return;
                _processedMsgIds.Add(xdo.MsgId);
                if (_processedMsgIds.Count > 1000) _processedMsgIds.Remove(_processedMsgIds.First());
            }
            if (!_msgChannel.Writer.TryWrite(xdo)) nlog.Error($"[Gateway:ERROR] Msg queue full: MsgId={xdo.MsgId}");
        }

        private async Task ProcessMessageQueueAsync(CancellationToken ct)
        {
            while (await _msgChannel.Reader.WaitToReadAsync(ct)) {
                while (_msgChannel.Reader.TryRead(out var xdo)) {
                    try {
                        _currentXdo = xdo;
                        _currentInfo = param.GetChannel(xdo.CID);
                        _msgSeq.SetState(HubState.Received);
                        int safety = 0; while (_msgSeq.IsInState(HubState.Received) && safety++ < 2) _msgSeq.Run();
                    } catch (Exception ex) { nlog.Error(ex, $"[Gateway:MSG] Error: MsgId={xdo?.MsgId}"); }
                }
            }
        }

        public async Task ProcessInterpretedSignalAsync(XDataObject xdo)
        {
            if (xdo == null) return;
            if (!_interpretedChannel.Writer.TryWrite(xdo)) nlog.Error($"[Gateway:ERROR] Interpreted queue full: SID={xdo.Signal?.sid}");
            await Task.CompletedTask;
        }

        private async Task ProcessInterpretedQueueAsync(CancellationToken ct)
        {
            while (await _interpretedChannel.Reader.WaitToReadAsync(ct)) {
                while (_interpretedChannel.Reader.TryRead(out var xdo)) {
                    try {
                        _currentInterpretedXdo = xdo;
                        _procSeq.SetState("Enrich");
                        int safety = 0; while (!_procSeq.IsInState("Idle") && safety++ < 3) await _procSeq.RunAsync();
                    } catch (Exception ex) { nlog.Error(ex, $"[Gateway:PROC] Error: MsgId={xdo?.MsgId}"); }
                }
            }
        }

        public XDataObject? GetNextSignal()
        {
            if (PendingSignals.IsEmpty) return null;
            var firstKey = PendingSignals.Keys.FirstOrDefault();
            if (firstKey != null && PendingSignals.TryRemove(firstKey, out var xdo)) { SignalRemoved?.Invoke(firstKey); return xdo; }
            return null;
        }
    }
}

