using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using XTA.Models;

namespace XTA.Services
{
    /// <summary>
    /// 시스템 상태 코드(XA_STATUS, XE_STATUS)의 명칭, 설명, UI 메타데이터를 중앙 관리하는 매니저.
    /// [Thread-Safe] ConcurrentDictionary를 사용하여 다중 스레드 환경에서 안전하게 상태 정보를 제공함.
    /// </summary>
    public class XStatusManager
    {
        private static readonly Lazy<XStatusManager> _instance = new Lazy<XStatusManager>(() => new XStatusManager());
        public static XStatusManager Instance => _instance.Value;

        private readonly ConcurrentDictionary<int, StatusInfo> _xaStatusMap = new ConcurrentDictionary<int, StatusInfo>();
        private readonly ConcurrentDictionary<int, StatusInfo> _xeStatusMap = new ConcurrentDictionary<int, StatusInfo>();

        private XStatusManager()
        {
            InitXaStatus();
            InitXeStatus();
        }

        private void InitXaStatus()
        {
            AddXa(0, "Raw", "메시지 수신 직후 (Raw Text)");
            AddXa(1, "Parsed", "분석 완료 (Interpreter 처리 완료)");
            AddXa(2, "Liquidation", "청산/취소 요청 상태");
            AddXa(3, "Waiting", "사용자 승인 대기 (Manual Mode)");
            AddXa(4, "Accepted", "진입 허용 (EA 전달 대상)");
            AddXa(5, "Revoke_Req", "사용자 취소 요청");
            AddXa(6, "Terminated", "프로세스 종료 완료");
            AddXa(9, "Dropped", "필터링 또는 무시됨");
        }

        private void InitXeStatus()
        {
            AddXe(0, "Ready", "초기 상태 (XE_READY)", "#808080");
