            AddXe(22, "Closed_IKTE", "익트(IkTe) 청산", "#00BFFF");
            AddXe(23, "Closed_SL", "손절(Stop Loss) 청산", "#FF4500");
            AddXe(24, "Closed_Manual", "사용자 수동 청산", "#A52A2A");
            AddXe(99, "Error", "에러 발생", "#FF0000");
        }

        private void AddXa(int code, string name, string desc) => _xaStatusMap.TryAdd(code, new StatusInfo(code, name, desc));
        private void AddXe(int code, string name, string desc, string color) => _xeStatusMap.TryAdd(code, new StatusInfo(code, name, desc, color));

        public StatusInfo GetXa(int code) => _xaStatusMap.TryGetValue(code, out var info) ? info : StatusInfo.Unknown(code);
        public StatusInfo GetXe(int code) => _xeStatusMap.TryGetValue(code, out var info) ? info : StatusInfo.Unknown(code);

        public string GetXaName(int code) => GetXa(code).Name;
        public string GetXeName(int code) => GetXe(code).Name;

        public class StatusInfo
        {
            public int Code { get; }
            public string Name { get; }
            public string Description { get; }
            public string Color { get; } // UI용 색상 코드 (Hex)

            public StatusInfo(int code, string name, string desc, string color = "#000000")
            {
                Code = code;
                Name = name;
                Description = desc;
                Color = color;
            }

            public static StatusInfo Unknown(int code) => new StatusInfo(code, "Unknown", $"알 수 없는 상태 ({code})");
        }
    }
