                        }
                    })

                .Builder()
                .DisableValidation()
                .Build();
        }

        public void PlaySound(XSignal? sig, string cmd, string text = "")
        {
            _currentXdo = new XDataObject { Signal = sig, CMD = cmd, Text = text };
            _currentTtsMsg = string.Empty;
            _sequence.SetState(SoundState.RequestReceived);

            int safetyCounter = 0;
