using FluentValidation;
using XTA.XData.Models;

namespace XTA.Validation
{
    public class XSignalValidator : AbstractValidator<XSignal>
    {
        public XSignalValidator()
        {
            // [공통 규칙]
            RuleFor(x => x.cno)
                .GreaterThan(0).WithMessage("채널 번호(CNO)는 0보다 커야 합니다.");

            // [청산 전용 규칙]: SID, CNO, SNO 세 가지 식별자만 중요
            When(x => x.cmd == "CLOSE", () =>
            {
                RuleFor(x => x.sno)
                    .GreaterThanOrEqualTo(0).WithMessage("청산 시 회차(SNO) 정보는 필수입니다.");

                // SID는 Validate() 메서드에서 생성되거나 인터프리터에서 할당됨
                RuleFor(x => x.sid)
                    .NotEmpty().When(x => x.sno > 0).WithMessage("개별 청산 시 SID는 필수입니다.");
            });

            // [진입 전용 규칙]: 심볼, 가격, 랏, 방향 모두 필수
            When(x => x.cmd != "CLOSE", () =>
            {
                RuleFor(x => x.symbol)
                    .NotEmpty().WithMessage("진입 시 심볼(Symbol)은 필수입니다.")
                    .MaximumLength(20).WithMessage("심볼이 너무 깁니다.");

                RuleFor(x => x.price_signal)
                    .GreaterThan(0)
                    .When(x => x.msg_id != -1) // 일반 신호는 0보다 커야 함
                    .WithMessage("진입 시 신호 가격은 0보다 커야 합니다.");

                RuleFor(x => x.price_signal)
                    .GreaterThanOrEqualTo(0)
                    .When(x => x.msg_id == -1) // 주입 신호는 0 이상 허용
                    .WithMessage("주입 신호의 가격은 0 이상이어야 합니다.");

                RuleFor(x => x.lot)
                    .GreaterThan(0).WithMessage("진입 시 랏(Lot)은 0보다 커야 합니다.");

                RuleFor(x => x.dir)
                    .Must(d => d == 1 || d == 2).WithMessage("진입 시 방향은 매수(1) 또는 매도(2)여야 합니다.");
            });
        }
    }
}

content:
`FluentValidation`은 비즈니스 로직에서 모델의 유효성 검사 규칙을 **강력한 형식(Strongly Typed)**과 **유창한 인터페이스(Fluent Interface)**로 분리하여 정의하는 라이브러리다.

### 1. 핵심 사용법
*   **`AbstractValidator<T>` 상속**: 검증할 모델 `T`에 대한 전용 클래스를 만든다.
*   **`RuleFor(x => x.Prop)`**: 특정 속성에 대한 검증 규칙을 체이닝 방식으로 선언한다.
*   **조건부 검증 (`When`, `Unless`)**: 특정 상황에서만 규칙을 적용한다.
*   **커스텀 에러 메시지 (`WithMessage`)**: 위반 시 사용자 정의 메시지를 반환한다.

### 2. XTA 적용 사례 (`XSignalValidator.cs`)
XTA에서는 `XSignal` 모델(거래 신호)의 무결성을 보장하기 위해 사용 중이다.

#### A. 명령별 조건부 규칙 (`When`)
거래 신호가 **진입(TRADE)**인지 **청산(CLOSE)**인지에 따라 검증 기준을 다르게 적용한다.
```csharp
// 청산(CLOSE)일 때: SNO와 SID 존재 여부가 핵심
When(x => x.cmd == "CLOSE", () => {
    RuleFor(x => x.sno).GreaterThanOrEqualTo(0);
});

// 진입(TRADE)일 때: 심볼, 가격, 랏, 방향 등 모든 데이터가 필수
When(x => x.cmd != "CLOSE", () => {
    RuleFor(x => x.symbol).NotEmpty();
    RuleFor(x => x.price_signal).GreaterThan(0);
    RuleFor(x => x.lot).GreaterThan(0);
});
```

#### B. 데이터 출처별 차등 규칙
일반 신호와 수동 주입 신호(`msg_id == -1`)의 가격 허용 범위를 다르게 설정한다.
```csharp
RuleFor(x => x.price_signal)
    .GreaterThan(0).When(x => x.msg_id != -1) // 일반 신호: 0 초과
    .GreaterThanOrEqualTo(0).When(x => x.msg_id == -1); // 주입 신호: 0 이상
```

### 3. 왜 쓰는가?
1.  **가독성**: `if-else` 지옥에서 벗어나 규칙이 한눈에 들어온다.
2.  **관심사 분리**: 모델 객체에 검증 로직을 넣지 않고 별도 클래스에서 관리하여 모델의 순수성을 유지한다. (XTA 정화 작업의 일환)
3.  **DI 연동**: `XTAHostBuilder`에서 서비스로 등록하여 필요한 곳에서 주입받아 사용할 수 있다.

현재 XTA 빌드에 포함되어 `XSignalService` 등에서 신호 저장 전 최종 검증 단계에서 활용된다. 더 궁금한 점 있나?

