using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using XTA.Models;

namespace XTA.Services
{
    /// <summary>
    /// 시스템 상태 코드(XA_STATUS, XE_STATUS)의 명칭, 설명, UI 메타데이터를 중앙 관리하는 매니저.
    /// [Thread-Safe] ConcurrentDictionary를 사용하여 다중 스레드 환경에서 안전하게 상태 정보를 제공함.
    /// </summary>
    public class XStatusManager
    {
        private static readonly Lazy<XStatusManager> _instance = new Lazy<XStatusManager>(() => new XStatusManager());
        public static XStatusManager Instance => _instance.Value;

        private readonly ConcurrentDictionary<int, StatusInfo> _xaStatusMap = new ConcurrentDictionary<int, StatusInfo>();
        private readonly ConcurrentDictionary<int, StatusInfo> _xeStatusMap = new ConcurrentDictionary<int, StatusInfo>();

        private XStatusManager()
        {
            InitXaStatus();
            InitXeStatus();
        }

        private void InitXaStatus()
        {
            AddXa(0, "Raw", "메시지 수신 직후 (Raw Text)");
            AddXa(1, "Parsed", "분석 완료 (Interpreter 처리 완료)");
            AddXa(2, "Liquidation", "청산/취소 요청 상태");
            AddXa(3, "Waiting", "사용자 승인 대기 (Manual Mode)");
            AddXa(4, "Accepted", "진입 허용 (EA 전달 대상)");
            AddXa(5, "Revoke_Req", "사용자 취소 요청");
            AddXa(6, "Terminated", "프로세스 종료 완료");
            AddXa(9, "Dropped", "필터링 또는 무시됨");
        }

        private void InitXeStatus()
        {
            AddXe(0, "Ready", "초기 상태 (XE_READY)", "#808080");
            AddXe(1, "PendingPlaced", "대기 오더 접수 중", "#FFA500");
            AddXe(2, "PendingVerified", "대기 오더 확인 완료", "#FFD700");
            AddXe(3, "TrlMonitoring", "트레일링 감시 시작", "#ADFF2F");
            AddXe(4, "TrlStarted", "트레일링 시작", "#7FFF00");
            AddXe(5, "TrlPriceMoved", "진입가 이동 완료", "#32CD32");
            AddXe(6, "ExecutingMarket", "시장가 전환 중", "#00FF7F");
            AddXe(10, "Executed", "체결 완료 (포지션 진입)", "#008000");
            AddXe(20, "Closed_Signal", "전략 신호에 의한 청산", "#4169E1");
            AddXe(21, "Closed_TP", "익절(Take Profit) 청산", "#1E90FF");
            AddXe(22, "Closed_IKTE", "익트(IkTe) 청산", "#00BFFF");
            AddXe(23, "Closed_SL", "손절(Stop Loss) 청산", "#FF4500");
            AddXe(24, "Closed_Manual", "사용자 수동 청산", "#A52A2A");
            AddXe(99, "Error", "에러 발생", "#FF0000");
        }

        private void AddXa(int code, string name, string desc) => _xaStatusMap.TryAdd(code, new StatusInfo(code, name, desc));
        private void AddXe(int code, string name, string desc, string color) => _xeStatusMap.TryAdd(code, new StatusInfo(code, name, desc, color));

        public StatusInfo GetXa(int code) => _xaStatusMap.TryGetValue(code, out var info) ? info : StatusInfo.Unknown(code);
        public StatusInfo GetXe(int code) => _xeStatusMap.TryGetValue(code, out var info) ? info : StatusInfo.Unknown(code);

        public string GetXaName(int code) => GetXa(code).Name;
        public string GetXeName(int code) => GetXe(code).Name;

        public class StatusInfo
        {
            public int Code { get; }
            public string Name { get; }
            public string Description { get; }
            public string Color { get; } // UI용 색상 코드 (Hex)

            public StatusInfo(int code, string name, string desc, string color = "#000000")
            {
                Code = code;
                Name = name;
                Description = desc;
                Color = color;
            }

            public static StatusInfo Unknown(int code) => new StatusInfo(code, "Unknown", $"알 수 없는 상태 ({code})");
        }
    }
}

using System;
using System.Collections.Concurrent;

namespace XTA.Services
{
    /// <summary>
    /// Magic Number 생성 규칙 및 Ticket-SID 매핑을 중앙 관리하는 매니저
    /// </summary>
    public class XTradeManager
    {
        private static readonly Lazy<XTradeManager> _instance = new Lazy<XTradeManager>(() => new XTradeManager());
        public static XTradeManager Instance => _instance.Value;

        // Ticket ID -> SID 매핑 캐시
        private readonly ConcurrentDictionary<long, string> _ticketToSidMap = new ConcurrentDictionary<long, string>();

        // SID -> Ticket ID 매핑 캐시
        private readonly ConcurrentDictionary<string, long> _sidToTicketMap = new ConcurrentDictionary<string, long>();

        private XTradeManager() { }

        /// <summary>
        /// 거버넌스 규칙에 따른 Magic Number 생성
        /// Format: CNO(3) + GNO(2) + SNO(4) (예시 규격)
        /// </summary>
        public long GenerateMagic(int cno, int gno, int sno)
        {
            // CNO(0~999), GNO(0~99), SNO(0~9999) 범위 가정
            return (long)(cno * 1000000) + (long)(gno * 10000) + (long)(sno % 10000);
        }

        /// <summary>
        /// 티켓과 SID를 매핑하여 등록
        /// </summary>
        public void RegisterTicket(long ticket, string sid)
        {
            if (ticket <= 0 || string.IsNullOrEmpty(sid)) return;

            _ticketToSidMap[ticket] = sid;
            _sidToTicketMap[sid] = ticket;
        }

        /// <summary>
        /// 티켓 번호로 SID 조회
        /// </summary>
        public string GetSidByTicket(long ticket)
        {
            return _ticketToSidMap.TryGetValue(ticket, out var sid) ? sid : string.Empty;
        }

        /// <summary>
        /// SID로 티켓 번호 조회
        /// </summary>
        public long GetTicketBySid(string sid)
        {
            return _sidToTicketMap.TryGetValue(sid, out var ticket) ? ticket : 0;
        }

        /// <summary>
        /// 앱 기동 시 DB로부터 활성 신호들의 티켓 매핑 정보를 로드하여 캐시 재구축
        /// </summary>
        public void Initialize(System.Collections.Generic.IEnumerable<XTA.XData.Models.XSignal> activeSignals)
        {
            if (activeSignals == null) return;

            _ticketToSidMap.Clear();
            _sidToTicketMap.Clear();

            int count = 0;
            foreach (var sig in activeSignals)
            {
                if (sig.ticket > 0 && !string.IsNullOrEmpty(sig.sid))
                {
                    RegisterTicket(sig.ticket, sig.sid);
                    count++;
                }
            }
        }
    }
}

using System;

namespace XTA.XData.Models
{
    /// <summary>
    /// XTA 시스템 공통 코드 및 상태 정의 (SSOT)
    /// XTA.XData 프로젝트로 이동하여 하위 레이어에서 공통 참조 가능하도록 함.
    /// </summary>
    public static class XCode
    {
        public const string NONE = "NONE";
        public const string TRADE = "TRADE";
        public const string OPEN = "TRADE"; // OPEN is an alias for TRADE
        public const string CLOSE = "CLOSE";
        public const string GRID = "GRID";
        public const int BUY = 1;
        public const int SELL = 2; // v7.5 Standard: 1=BUY, 2=SELL
        public const string GROUP_CLOSE = "GROUP_CLOSE";
        public const string INFO = "INFO";
        // --- 그리드 체계 (G0 ~ G4) ---
        public const int GNO_MASTER = 0;    // G0: 첫 번째 그리드이자 메인 신호
        public const int GNO_MAX = 4;       // 최대 G4까지 가능

        // --- 주문 타입 체계 (XABC v3.5 표준 - CXDefine.mqh 해석) ---
        public const int TYPE_CLOSE = 0;           // 청산 (Liquidation - SID)
        public const int TYPE_LIMIT_TRAILING = 1;  // Type 1: 리미트 트레일링 (Limit Trailing)
        public const int TYPE_LIMIT = 2;           // Type 2: 리미트 (Limit)
        public const int TYPE_STOP = 3;            // Type 3: 스탑 (Stop)
        public const int TYPE_MARKET = 9;          // Type 9: 시장가 (Market)
        /// <summary>
        /// 청산 타입 체계 ---
        /// </summary>
        public const int CLOSE_SID = 0;            // 단일 청산 (SID)
        public const int CLOSE_GROUP = 9;          // 그룹 청산 (GID)

        public const int XA_RAW = 0;               // 초기 상태 (Intent Raw)
        public const int XA_ACTIVE = 1;            // 활성 상태 (Intent Active)


        /// <summary>
        /// EA(MQL5)에서 사용하는 신호 실행 상태 코드 (Lifecycle v4.0 - CXDefine.mqh 동기화)
        /// </summary>
        public enum EaStatus
        {
            Ready = 0,            // 초기 상태 (XE_READY)
            PendingPlaced = 1,    // 대기 오더 접수 중 (XE_PENDING_PLACED)
            PendingVerified = 2,  // 대기 오더 확인 완료 (XE_PENDING_VERIFIED)
            TrlMonitoring = 3,    // 대기 오더 트레일링 감시 시작 (XE_TRL_MONITORING)
            TrlStarted = 4,       // 트레일링 시작 (XE_TRL_STARTED)
            TrlPriceMoved = 5,    // 트레일링 진입가 이동 (XE_TRL_PRICE_MOVED)
            ExecutingMarket = 6,  // 시장가 전환 중 (XE_EXECUTING_MARKET)
            Executed = 10,        // 체결 완료 / 포지션 진입 (XE_EXECUTED)

            // [v1.5] 익절 트레일링(IkTe) 전용 상태 코드
            IkTeStarted = 15,     // 익절 트레일링 시작 (XE_IKTE_STARTED)
            IkTePriceMoved = 16,  // 익절 트레일링 가격 이동 (XE_IKTE_PRICE_MOVED)

            // [v1.3 Patch] 청산 상세 상태 코드 (XE_CLOSED_XXX)
            Closed_Signal = 20,   // 신호 청산 (XE_CLOSED_SIGNAL)
            Closed_TP = 21,       // 익절 청산 (XE_CLOSED_TP)
            Closed_IKTE = 22,     // 익트 청산 (XE_CLOSED_IKTE)
            Closed_SL = 23,       // 손절 청산 (XE_CLOSED_SL)
            Closed_Manual = 24,   // 수동 청산 (XE_CLOSED_MANUAL)

            Error = 99            // 에러 발생 (XE_ERROR)
        }
    }
}

