using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Linq;
using System.Windows.Input;
using ATSA.UI.UCtrls;
using ATSA.UI.UCtrls.TGMsg;
using ATSA.UI.Models;
using DevExpress.Mvvm;
using XTA.Models;
using XTA.Core;
using XTA.Services.TelegramService;
using XTA.Interfaces;

namespace ATSA.UI.Dashboard
{
    public class DashboardViewModel : ViewModelBase
    {
        public UCXSignalViewModel Channel1001 { get; } = new UCXSignalViewModel("CNO 1001");
        public UCXSignalViewModel Channel1002 { get; } = new UCXSignalViewModel("CNO 1002");
        public UCXSignalViewModel Channel3001 { get; } = new UCXSignalViewModel("CNO 3001");
        public UCXSignalViewModel Channel3002 { get; } = new UCXSignalViewModel("CNO 3002");

        public UCXTGMsgViewModel MsgLog1001 { get; } = new UCXTGMsgViewModel(1001);
        public UCXTGMsgViewModel MsgLog1002 { get; } = new UCXTGMsgViewModel(1002);
        public UCXTGMsgViewModel MsgLog3001 { get; } = new UCXTGMsgViewModel(3001);
        public UCXTGMsgViewModel MsgLog3002 { get; } = new UCXTGMsgViewModel(3002);

        public int RefreshInterval { get; set; } = 1;

        public ICommand ToggleRefreshCommand { get; }
        public ICommand SampleCommand { get; }

        private readonly Dictionary<int, UCXTGMsgViewModel> _msgLogByCno;
        private readonly Dictionary<int, UCXSignalViewModel> _signalChannels;

        public DashboardViewModel()
        {
            ToggleRefreshCommand = new DelegateCommand(GenerateMockData);
            SampleCommand = new DelegateCommand(GenerateSampleData);

            _msgLogByCno = new Dictionary<int, UCXTGMsgViewModel>
            {
                { 1001, MsgLog1001 }, { 1002, MsgLog1002 },
                { 3001, MsgLog3001 }, { 3002, MsgLog3002 }
            };

            _signalChannels = new Dictionary<int, UCXSignalViewModel>
            {
                { 1001, Channel1001 }, { 1002, Channel1002 },
                { 3001, Channel3001 }, { 3002, Channel3002 }
            };

            System.Diagnostics.Debug.WriteLine($"[DashboardViewModel:CTOR] Initializing Dashboard ViewModel");

            // 엔진 이벤트 구독
            SubscribeToEngineEvents();
        }

        private void SubscribeToEngineEvents()
        {
            var ctx = XContext.Instance;

            // 1. 텔레그램 메시지 실시간 수신 이벤트 (XTelegram)
            var tg = ctx.GetService<XTelegram>();
            if (tg != null)
            {
                tg.MessageReceived += xdo => OnTelegramMessageReceived(xdo);
                System.Diagnostics.Debug.WriteLine("[Dashboard] Subscribed to XTelegram.MessageReceived");
            }

            // 2. 신호 주입/업데이트 이벤트 (XGatewayService)
            if (ctx.Gateway != null)
            {
                ctx.Gateway.SignalAddedOrUpdated += xdo => OnSignalUpdated(xdo);
                System.Diagnostics.Debug.WriteLine("[Dashboard] Subscribed to XGateway.SignalAddedOrUpdated");
            }
        }

        private void OnTelegramMessageReceived(XDataObject xdo)
        {
            if (xdo == null || !_msgLogByCno.ContainsKey(xdo.CNO)) return;

            System.Windows.Application.Current?.Dispatcher.Invoke(() =>
            {
                var msgVM = _msgLogByCno[xdo.CNO];
                msgVM.Messages.Insert(0, new XTA.Models.XTgMessage { 
                    Time = DateTime.Now, 
                    Text = $"[{xdo.CName}] {xdo.Text}" 
                });
                if (msgVM.Messages.Count > 500) msgVM.Messages.RemoveAt(msgVM.Messages.Count - 1);
            });
        }

        private void OnSignalUpdated(XDataObject xdo)
        {
            if (xdo?.Signal == null || !_signalChannels.ContainsKey(xdo.CNO)) return;

            System.Windows.Application.Current?.Dispatcher.Invoke(() =>
            {
                var channel = _signalChannels[xdo.CNO];
                // XTA의 순수 모델을 UI용 Bindable 모델로 변환하여 처리
                var bindable = BindableXSignal.FromModel(xdo.Signal);
                channel.UpdateSignal(bindable);
            });
        }

        private void GenerateSampleData()
        {
            foreach (var ch in _signalChannels.Values)
            {
                ch.Signals.Clear();
                for (int i = 1; i <= 20; i++)
                    ch.AddMockSignal($"{ch.ChannelName.Replace(" ", "-")}-S{i}", i % 2 + 1, 0.1 * i, 2300 + i * 10);
            }

            foreach (var logVM in _msgLogByCno.Values)
            {
                logVM.Messages.Clear();
                for (int i = 1; i <= 20; i++)
                    logVM.Messages.Add(new XTgMessage { Time = DateTime.Now, Text = $"Sample TG Message {i} with long text wrapping test to ensure multi-line display works correctly." });
            }
        }

        protected void GenerateMockData()
        {
            foreach (var ch in _signalChannels.Values)
            {
                ch.Signals.Clear();
                for (int i = 1; i <= 3; i++)
                    ch.AddMockSignal($"{ch.ChannelName.Replace(" ", "-")}-{i}", i % 2 + 1, 0.1 * i, 2300 + i * 10);
            }

            foreach (var logVM in _msgLogByCno.Values)
            {
                logVM.Messages.Clear();
                for (int i = 1; i <= 5; i++)
                    logVM.Messages.Add(new XTgMessage { Time = DateTime.Now, Text = $"Raw TG Message {i}" });
            }
        }
    }

    public class DashboardViewModelDesign : DashboardViewModel
    {
        public DashboardViewModelDesign() { GenerateMockData(); }
    }
}

using DevExpress.Mvvm;
using DevExpress.Mvvm.DataAnnotations;
using System;
using System.Collections.ObjectModel;
using System.Linq;
using System.Threading.Tasks;
using XTA.Models;
using XTA.Infrastructure.Data;
using DevExpress.Xpo;
using XTA.XData.Models;
using DevExpress.Data.Filtering;
using XTA.Extensions;
using XTA.XData.Services;

namespace ATSA.UI.UCtrls
{
    public class UCXTGMsgViewModel : ViewModelBase
    {
        private readonly XParameter? _param;
        public int CNO { get; }
        public ObservableCollection<XTA.Models.XTgMessage> Messages { get; } = new();

        public UCXTGMsgViewModel(int cno)
        {
            _param = App.Param;
            CNO = cno;

            if (_param != null)
            {
                RegisterHandler();
                _ = RefreshFromDbAsync();
            }
        }

        private void RegisterHandler()
        {
            string channelName = $"TG_MSG_LOG_CNO{CNO}";
            _param?.messenger.Register<XDataObject>(this, channelName, true, xdo =>
            {
                if (xdo == null) return;

                var msg = new XTA.Models.XTgMessage
                {
                    Time = xdo.Timestamp == DateTime.MinValue ? DateTime.Now : xdo.Timestamp,
                    CNO = CNO,
                    CID = xdo.CID,
                    Text = xdo.Text ?? string.Empty,
                    CreatedAt = DateTime.Now
                };

                System.Windows.Application.Current?.Dispatcher.Invoke(() =>
                {
                    Messages.Insert(0, msg);
                    if (Messages.Count > 500) Messages.RemoveAt(Messages.Count - 1);
                });
            });
        }

        [Command]
        public async Task RefreshFromDbAsync()
        {
            var db = _param?.GetService<XpoSqliteService>();
            if (db == null) return;

            try
            {
                var criteria = CriteriaOperator.Parse("CNO = ?", CNO);
                var sorts = new[] { new SortProperty("Time", DevExpress.Xpo.DB.SortingDirection.Descending) };

                var xpoMsgs = await db.GetLayer().FindListAsync<XpoTgMessage>(criteria, sorts);

                var domainMsgs = xpoMsgs.Take(100).Select(x => x.ToDomainModel()).ToList();

                System.Windows.Application.Current?.Dispatcher.Invoke(() =>
                {
                    Messages.Clear();
                    foreach (var m in domainMsgs) 
                    {
                        Messages.Add(new XTA.Models.XTgMessage 
                        { 
                            Oid = (int)m.Id,
                            CID = m.CID,
                            Time = m.Time,
                            CNO = m.CNO,
                            Text = m.Text,
                            Status = m.Status
                        });
                    }
                });
            }
            catch (Exception ex)
            {
                _param?.nlog.Error(ex, $"[UCXTGMsgViewModel] Refresh Error for CNO {CNO}");
            }
        }
    }

    public class UCXTGMsgViewModelDesign : ViewModelBase
    {
        public ObservableCollection<XTA.Models.XTgMessage> Messages { get; } = new();
        public UCXTGMsgViewModelDesign()
        {
            for (int i = 1; i <= 5; i++)
            {
                Messages.Add(new XTA.Models.XTgMessage { Time = DateTime.Now.AddMinutes(-i), Text = $"Design Time Telegram Message {i}" });
            }
        }
    }
}

