using System;
using System.Threading.Tasks;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using XTA.Core;
using XTA.Models;

namespace XTA
{
    /// <summary>
    /// .NET IHost 기반으로 고도화된 최종 XTA 스타트업 엔진
    /// </summary>
    public class XTAStartupV2
    {
        private static NLog.Logger nlog = NLog.LogManager.GetCurrentClassLogger();

        public static async Task RunAsync()
        {
            var ctx = XContext.Instance;
            nlog.Info("[Startup] Starting XTA V2 Host Startup...");

            try
            {
                // 1. 파라미터 초기화
                nlog.Trace("[Startup] Initializing XParameter...");
                var parameter = new XParameter();
                ctx.Parameter = parameter;

                // 2. IHost 빌드 및 XContext 바인딩
                nlog.Trace("[Startup] Building Standard Host...");
                var host = XTAHostBuilder.Build(ctx.Parameter);
                ctx.Initialize(host, ctx.Parameter);

                // 3. Host 실행 (백그라운드 서비스들 시작)
                nlog.Trace("[Startup] Starting IHost...");
                await ctx.GetService<IHost>().StartAsync();

                // 4. 기존 XObject 기반 서비스들 시작 (호환성 유지)
                nlog.Trace("[Startup] Starting Legacy Services...");
                ctx.Parameter.StartAll();

                nlog.Info("[Startup] XTA V2 Host Startup completed successfully.");
            }
            catch (Exception ex)
            {
                nlog.Fatal(ex, $"[Startup:FATAL] Host startup failed: {ex.Message}");
                throw;
            }
        }

        /// <summary>
        /// 데이터 이관 작업
        /// </summary>
        public static async Task ProcessTransferAsync()
        {
            var ctx = XContext.Instance;
            nlog.Info("[Transfer] Starting Data Transfer...");

            try
            {
                var repo = ctx.SignalRepo;
                if (repo == null) return;

                var closedSignals = await repo.GetClosedSignalsAsync();
                if (closedSignals.Count > 0)
                {
                    var dataSvc = ctx.Data;
                    if (dataSvc != null)
                    {
                        nlog.Info($"[Transfer] Moving {closedSignals.Count} closed signals to history...");
                        await dataSvc.ArchiveSignalsAsync();
                    }
                }
                nlog.Info("[Transfer] Data Transfer completed.");
            }
            catch (Exception ex)
            {
                nlog.Error(ex, $"[Transfer:ERROR] Data transfer failed: {ex.Message}");
            }
        }
    }
}

