using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using TL;
using XTA.Models;
using XTA.Core;

namespace XTA.Services.TelegramService
{
    public class XTelegram : XTelegramBase
    {
        /// <summary>
        /// 텔레그램 메시지 수신 시 발생하는 이벤트 (UI 대시보드 로그용)
        /// </summary>
        public event Action<XDataObject>? MessageReceived;

        public XTelegram(XParameter param) : base(param)
        {
        }

        public override void Start()
        {
            base.Start();
            nlog?.Trace("[XTelegram] Service class specific Start completed.");
        }

        public override void ProcessSignal(XDataObject xdo)
        {
            if (xdo == null || xdo.CID != this.CID) return;
            nlog?.Trace($"[SIGNAL_PROCESS] CID:{CID} Received Signal Context: {xdo.Text}");
        }

        protected override Task HandleUpdate(UpdatesBase updates)
        {
            if (updates == null) return Task.CompletedTask;

            foreach (var update in updates.UpdateList)
            {
                TL.Message? msg = null;

                if (update is UpdateNewChannelMessage uncm && uncm.message is TL.Message m1) msg = m1;
                else if (update is UpdateNewMessage unm && unm.message is TL.Message m2) msg = m2;

                if (msg == null) continue;

                long rawId = msg.peer_id.ID;
                long peerId = rawId;

                string channelTitle = "Unknown";
                if (updates.Chats.TryGetValue(rawId, out var chat)) channelTitle = chat.Title ?? "Unknown";

                nlog.Trace($"[TG:DEBUG] Incoming Update: PeerID:{rawId} (Title:\"{channelTitle}\") | MsgId:{msg.id}");

                if (!param.Channels.ContainsKey(peerId))
                {
                    var matchedInfo = param.Channels.Values.FirstOrDefault(c =>
                        c.CID == rawId ||
                        Math.Abs(c.CID % 10000000000L) == Math.Abs(rawId % 10000000000L) ||
                        (uint)c.CID == (uint)rawId ||
                        (int)c.CID == (int)rawId
                    );

                    if (matchedInfo != null)
                    {
                        peerId = matchedInfo.CID;
                        nlog.Info($"[SIGNAL:STEP-0:MATCH] PeerID {rawId} fuzzy-matched to Registered CID {peerId} ({matchedInfo.Name})");
                    }
                    else
                    {
                        continue;
                    }
                }
                string summary = msg.message.Replace("\n", " ");
                if (summary.Length > 50) summary = summary.Substring(0, 50) + "...";

                nlog.Info($"[SIGNAL:STEP-0:RECEIVE] TG Update Detected. MsgId:{msg.id} | RawPeer:{rawId} (\"{channelTitle}\") | Text:{summary}");

                var info = param.GetChannel(peerId);
                if (info == null) continue;

                nlog.Info($"[SIGNAL:STEP-0:ACCEPT] CID:{peerId} | CNO:{info.CNO} | Name:{info.Name} | MsgId:{msg.id}");

                XDataObject xdo = new XDataObject()
                {
                    Sender = this.GetType().Name,
                    CID = peerId,
                    Text = msg.message,
                    CName = channelTitle,
                    CNO = info.CNO,
                    Timestamp = msg.date,
                    MsgId = msg.id
                };

                try
                {
                    // 1. 게이트웨이 서비스로 직접 전송
                    XContext.Instance.Gateway?.EnqueueRawMessage(xdo);
                    nlog.Info($"[SIGNAL:STEP-0:DISPATCH] Dispatched MsgId:{msg.id} to Gateway Service.");

                    // 2. 외부(UI 등) 구독자에게 알림 (구 DashboardChannel 대체)
                    MessageReceived?.Invoke(xdo);
                    nlog.Info($"[SIGNAL:STEP-0:DASHBOARD] Broadcasted TG message event for CNO:{info.CNO}");
                }
                catch (Exception ex)
                {
                    nlog.Error(ex, $"[TG:DISPATCH] Dispatch Error. MsgId:{msg.id}");
                }
            }

            return Task.CompletedTask;
        }
    }
}

using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using System.Timers;
using TL;
using WTelegram;
using XTA.Models;

namespace XTA.Services.TelegramService
{
    /// <summary>
    /// WTelegram 기반 텔레그램 서비스 기본 클래스
    /// </summary>
    public class XTelegramBase : XChannelObject, IDisposable
    {
        private Client? _client;
        public static Client? Client { get; private set; }

        private readonly System.Timers.Timer _timer;
        private readonly SemaphoreSlim _loginLock = new SemaphoreSlim(1, 1);
        private bool _isDisposed = false;
        private readonly object _syncRoot = new object();

        public int Interval { get; set; } = 30000;
        public bool Auto { get; set; } = true;

        public string? TgApiId { get; set; } = "9150286";
        public string? TgApiHash { get; set; } = "bf8036c4b7390a0abc2d3977874f18d0";
        public string? TgPhoneNumber { get; set; } = "+821071697000";
        public string? TgVerificationCode { get; set; }

        public XTelegramBase(XParameter param) : base(param, new XChannelInfo(0, 0, "Telegram Service", "SYSTEM"))
        {
            _timer = new System.Timers.Timer();
            _timer.Elapsed += OnTimerElapsed;
        }

        public override void ProcessSignal(XDataObject xdo)
        {
            if (xdo == null || xdo.CID != this.CID) return;
        }

        private async void OnTimerElapsed(object? sender, ElapsedEventArgs e)
        {
            if (_client == null || _isDisposed) return;
            try
            {
                if (_client.Disconnected)
                {
                    if (Auto)
                    {
                        nlog.Warn("[TG:STATUS] Client disconnected. Attempting auto-login...");
                        await _client.LoginUserIfNeeded();
                    }
                }
                else
                {
                    nlog.Trace("[TG:STATUS] Client is active. Sending keep-alive ping.");
                    await _client.Ping(DateTime.Now.Ticks);
                }
            }
            catch (Exception ex) { nlog?.Error(ex, "[TG:TIMER] Error during status check/ping"); }
        }

        public override void Start()
        {
            nlog.Info("[TG:START] Telegram Service Start requested.");
            _ = StartClientAsync();
        }

        public override void Stop()
        {
            nlog.Info("[TG:STOP] Telegram Service Stop requested.");
            Dispose();
        }

        public void Dispose()
        {
            if (_isDisposed) return;
            lock (_syncRoot)
            {
                if (_isDisposed) return;
                _isDisposed = true;
                _timer?.Stop();
                _timer?.Dispose();
                _client?.Dispose();
                nlog?.Info($"[TG:DISPOSE] {GetType().Name} Disposed (CID: {CID})");
            }
        }

        private async Task StartClientAsync()
        {
            if (string.IsNullOrEmpty(TgApiId))
            {
                nlog?.Fatal("[TG:INIT] TgApiId is not set. Aborting startup.");
                return;
            }

            nlog.Info($"[TG:INIT] Initializing WTelegram Client (Phone: {TgPhoneNumber})");

            await _loginLock.WaitAsync();
            try
            {
                if (_client != null && !_client.Disconnected)
                {
                    nlog.Info("[TG:INIT] Client is already connected.");
                    return;
                }

                _client ??= new Client(what => what switch
                {
                    "api_id" => TgApiId,
                    "api_hash" => TgApiHash,
                    "phone_number" => TgPhoneNumber,
                    "verification_code" => TgVerificationCode,
                    _ => null
                });

                _client.OnUpdates -= HandleUpdate;
                _client.OnUpdates += HandleUpdate;
                nlog.Debug("[TG:EVENT] Update handler registered before login.");

                nlog.Info("[TG:LOGIN] Attempting to login...");
                var status = await _client.LoginUserIfNeeded();

                if (_client.Disconnected)
                {
                    nlog.Error($"[TG:LOGIN] Login failed. Client state: Disconnected. Status: {status}");
                    return;
                }

                nlog.Info($"[TG:LOGIN] Success. Logged in as: {_client.User}");

                _timer.Interval = Interval;
                _timer.Start();
                nlog.Debug($"[TG:TIMER] Auto-reconnect timer started.");

                Client = _client;
            }
            catch (Exception ex)
            {
                nlog?.Fatal(ex, "[TG:FATAL] Exception during StartClientAsync");
            }
            finally { _loginLock.Release(); }
        }

        protected virtual Task HandleUpdate(UpdatesBase updates)
        {
            nlog.Trace($"[TG:BASE_UPDATE] Base HandleUpdate reached. Type: {updates?.GetType().Name}");
            return Task.CompletedTask;
        }
    }
}

