        public event PropertyChangedEventHandler? PropertyChanged
        {
            add => _bindableHelper.PropertyChanged += value;
            remove => _bindableHelper.PropertyChanged -= value;
        }

        protected void RaisePropertyChanged(string propertyName)
        {
            // BindableBase의 protected 메서드를 호출하기 위해 상속받은 별도 헬퍼 클래스가 필요할 수 있으나,
            // 여기서는 단순성을 위해 직접 구현하거나 Delegate 활용.
            _bindableHelper.GetType().GetMethod("RaisePropertyChanged", 
                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance, 
                new[] { typeof(string) })?.Invoke(_bindableHelper, new object[] { propertyName });
        }

