using System;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using NLog.Extensions.Logging;
using XTA.Core;
using XTA.Interfaces;
using XTA.Infrastructure.Data;
using XTA.Infrastructure.Audio;
using XTA.Services;
using XTA.Services.TelegramService;
using XTA.Models;
using XTA.XData.Interfaces;

namespace XTA
{
    /// <summary>
    /// .NET IHost 빌드를 담당하는 팩토리 클래스
    /// </summary>
    public static class XTAHostBuilder
    {
        public static IHost Build(XParameter parameter, Action<IServiceCollection>? extraServices = null)
        {
            var host = Host.CreateDefaultBuilder()
                .ConfigureLogging(logging =>
                {
                    logging.ClearProviders();
                    logging.SetMinimumLevel(Microsoft.Extensions.Logging.LogLevel.Trace);
                    logging.AddNLog(); // NLog 연동
                })
                .ConfigureServices((hostContext, services) =>
                {
                    // 1. 인프라 서비스 (싱글톤)
                    var dbService = new XpoSqliteService(parameter);
                    services.AddSingleton<XpoSqliteService>(dbService);
                    services.AddSingleton<ISignalRepository>(dbService);
                    services.AddSingleton<IDataService>(new XDataService(parameter));

                    // 2. 도메인 서비스
                    services.AddSingleton<IXTradePolicyService, XTradePolicyService>();
                    services.AddSingleton<IXLiquidationService, XLiquidationService>();
                    services.AddSingleton<IXSignalService, XSignalService>();
                    services.AddSingleton<IXGatewayService>(new XGatewayService(parameter));

                    // 3. 알림 및 유틸리티
                    services.AddSingleton<ISoundService>(new XSoundService(parameter));
                    services.AddSingleton<ITtsService>(new XTtsService(parameter));

                    // 4. 백그라운드 워커 (HostedService 가능성 열어둠)
                    services.AddSingleton(new XSyncWorker(parameter));

                    // XTelegram은 기본값으로 등록하되, extraServices에서 덮어쓸 수 있도록 함.
                    services.AddSingleton<XTelegram>(sp => new XTelegram(parameter));

                    // 5. 전역 파라미터 등록
                    services.AddSingleton(parameter);

                    // 6. 추가 서비스 등록 (오버라이드 허용)
                    extraServices?.Invoke(services);
                })
                .Build();

            return host;
        }
    }
}

