using System;
using System.Text;

namespace XTA.Channels.GMK
{
    public static class GMKTemplate
    {
        public static string Generate(int sno, string symbol, int dir, double lot, double price, bool isExit, double exitPrice = 0)
        {
            string timeStr = DateTime.Now.ToString("yyyy.MM.dd HH:mm:ss");
            string color = dir == 1 ? "🔵" : "🔴";
            string dirStr = dir == 1 ? "BUY" : "SELL";
            string sep = "━━━━━━━━━━━━━━";

            if (isExit)
            {
                double currentExitPrice = exitPrice > 0 ? exitPrice : price;
                double pnl = (currentExitPrice - price) * (dir == 1 ? 1 : -1) * lot * 100; // Dummy PnL calculation

                return $@"💥 포지션 정리
{sep}
📌 청산 신호 공유
{sep}

📌 일시 : {timeStr}
📌 심볼 : {symbol}
{color} 포지션 : {dirStr}
📌 랏수 : {lot:N2} lot
📌 진입가 : {price:N2}
📌 청산가 : {currentExitPrice:N2}
💧 실현손익 : {pnl:N2} 달러
📌 횟차 : {sno}차 정리

🎉 수익 구간은 함께 축하하고
💧 손실 구간은 리스크 관리 기준으로 대응합니다.";
            }
            else
            {
                return $@"🟡 {symbol.Split(' ')[0]} 포지션 진입
{sep}
📌 진입 신호 공유
{sep}

📌 일시 : {timeStr}
📌 심볼 : {symbol}
{color} 포지션 : {dirStr}
📌 랏수 : {lot:N2} lot
📌 진입가 : {price:N2}
📌 횟차 : {sno}차 진입

📍 실시간 포지션 참고용 공유입니다.";
            }
        }
    }
}

