    /// <summary>
    /// XTA.Models.XSignal을 상속받아 UI 바인딩 기능을 추가한 확장 클래스 (dxmvvm 버전)
    /// </summary>
    public class BindableXSignal : XTA.Models.XSignal, IBindableBase
    {
        // BindableBase의 기능을 수동으로 구현하거나 상속 구조상 래핑이 필요함.
        // 여기서는 XSignal이 이미 다른 클래스를 상속받지 않으므로 직접 상속도 가능하지만, 
        // XTA.Models.XSignal이 이미 XTA.XData.Models.XSignal을 상속받고 있음.
        // 다중 상속 불가하므로 Helper를 쓰거나 필요한 속성만 재정의.

        private readonly BindableBase _bindableHelper = new BindableBase();

        // IBindableBase 구현 (필요시)
        public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged 
        { 
            add => _bindableHelper.PropertyChanged += value; 
            remove => _bindableHelper.PropertyChanged -= value; 
        }

        protected void RaisePropertyChanged(string propertyName)
        {
            _bindableHelper.RaisePropertyChanged(propertyName);
        }

        protected bool SetProperty<T>(ref T storage, T value, string propertyName)
        {
            if (System.Collections.Generic.EqualityComparer<T>.Default.Equals(storage, value)) return false;
            storage = value;
            RaisePropertyChanged(propertyName);
            return true;
        }

        // --- 바인딩이 필요한 속성들 오버라이드 및 UI 전용 속성 ---
        public new int xa_entry { get => base.xa_entry; set { if (base.xa_entry != value) { base.xa_entry = value; RaisePropertyChanged(nameof(xa_entry)); } } }
        public new int xa_exit { get => base.xa_exit; set { if (base.xa_exit != value) { base.xa_exit = value; RaisePropertyChanged(nameof(xa_exit)); } } }
        public new int xe_status { get => base.xe_status; set { if (base.xe_status != value) { base.xe_status = value; RaisePropertyChanged(nameof(xe_status)); } } }
        public new string xe_status_msg { get => base.xe_status_msg; set { if (base.xe_status_msg != value) { base.xe_status_msg = value; RaisePropertyChanged(nameof(xe_status_msg)); } } }
        public new double price { get => base.price; set { if (base.price != value) { base.price = value; RaisePropertyChanged(nameof(price)); } } }

        private bool _isHighlight;
        public new bool isHighlight { get => _isHighlight; set => SetProperty(ref _isHighlight, value, nameof(isHighlight)); }

        private bool _isSelected;
        public bool IsSelected { get => _isSelected; set => SetProperty(ref _isSelected, value, nameof(IsSelected)); }

        public static BindableXSignal FromModel(XTA.Models.XSignal model)
        {
            var bindable = new BindableXSignal();
            XTA.Models.XSignal.UpdateFromBase(bindable, model);
            bindable.sid_date = model.sid_date;
            bindable.isHighlight = model.isHighlight;
            return bindable;
        }
    }
}

