using DevExpress.Mvvm;
using DevExpress.Mvvm.DataAnnotations;
using System;
using System.Collections.ObjectModel;
using System.Linq;
using System.Threading.Tasks;
using XTA.Models;
using ATSA.UI.Models;
using XTA.Core;
using XTA.XData.Interfaces;

namespace ATSA.UI.DataManager
{
    public class DataManagerViewModel : ViewModelBase
    {
        private readonly XParameter _param;

        public ObservableCollection<BindableXSignal> SignalList { get; } = new();

        private BindableXSignal? _selectedSignal;
        public BindableXSignal? SelectedSignal 
        { 
            get => _selectedSignal; 
            set => SetProperty(ref _selectedSignal, value, nameof(SelectedSignal)); 
        }

        public DataManagerViewModel()
        {
            _param = XContext.Instance.Parameter;
            _ = LoadSignalsAsync();
        }

        [Command]
        public async Task LoadSignalsAsync()
        {
            var repo = XContext.Instance.GetService<ISignalRepository>();
            if (repo == null) return;

            try
            {
                var signals = await repo.GetSignalsByCnoAsync(0, 1000); // 전체 신호 로드

                System.Windows.Application.Current?.Dispatcher.Invoke(() =>
                {
                    SignalList.Clear();
                    foreach (var s in signals)
                    {
                        SignalList.Add(BindableXSignal.FromModel(XTA.Models.XSignal.FromBase(s)));
                    }
                });
            }
            catch (Exception ex)
            {
                _param.nlog.Error(ex, "[DM] Failed to load signals from database.");
            }
        }

        [Command]
        public async Task SaveChangesAsync()
        {
            if (SelectedSignal == null) return;

            var repo = XContext.Instance.GetService<ISignalRepository>();
            if (repo == null) return;

            try
            {
                await repo.SaveSignalAsync(SelectedSignal);
                _param.nlog.Info($"[DM] Signal {SelectedSignal.sid} updated manually via DM.");
            }
            catch (Exception ex)
            {
                _param.nlog.Error(ex, "[DM] Failed to save signal changes.");
            }
        }

        [Command]
        public void AddNewSignal()
        {
            var newSig = new BindableXSignal { sid = DateTime.Now.ToString("yyyyMMdd-HHmm-ss-000") };
            SignalList.Insert(0, newSig);
            SelectedSignal = newSig;
        }
    }
}

