using DevExpress.Mvvm;
using System.Windows.Input;

namespace ATSA.UI.Main
{
    public class MainViewModel : ViewModelBase
    {
        private object _currentView = null!;
        public object CurrentView
        {
            get => _currentView;
            set => SetProperty(ref _currentView, value, nameof(CurrentView));
        }

        public ICommand ShowDashboardCommand { get; }
        public ICommand ShowDataManagerCommand { get; }

        public MainViewModel()
        {
            ShowDashboardCommand = new DelegateCommand(() => CurrentView = new Dashboard.DashboardViewModel());
            ShowDataManagerCommand = new DelegateCommand(() => CurrentView = new DataManager.DataManagerViewModel());

            // 초기 화면: 대시보드
            CurrentView = new Dashboard.DashboardViewModel();
        }
    }
}
